def pluck(arr):
    if not arr:
        return []

    smallest_even = None
    smallest_index = float('inf')

    for index, value in enumerate(arr):
        if value % 2 == 0 and value <= smallest_even or smallest_even is None:
            smallest_even = value
            smallest_index = index

    return [smallest_even, smallest_index] if smallest_even is not None else []
